function PackageMeasurements({ profile }: { profile?: NonNullable<Data['equipment'][number]['packageProfile']> }) {
    const [unit, setUnit] = useState<MeasurementUnit>(profile?.enteredUnit || 'US');
    const [canonical, setCanonical] = useState({ length: profile?.lengthCm || 0, width: profile?.widthCm || 0, height: profile?.heightCm || 0, weight: profile?.weightKg || 0 });
    const [entry, setEntry] = useState<Record<string, string>>({
        length: profile ? rounded(toDisplayLength(canonical.length, unit)) : '',
        width: profile ? rounded(toDisplayLength(canonical.width, unit)) : '',
        height: profile ? rounded(toDisplayLength(canonical.height, unit)) : '',
        weight: profile ? rounded(toDisplayWeight(canonical.weight, unit)) : ''
    });
    const changeUnit = (next: MeasurementUnit) => {
        setUnit(next);
        setEntry(Object.fromEntries((['length','width','height','weight'] as const).map(k => [k, entry[k] === '' ? '' : rounded(k === 'weight' ? toDisplayWeight(canonical[k], next) : toDisplayLength(canonical[k], next))])));
    };
    const edit = (key: 'length' | 'width' | 'height' | 'weight', raw: string) => {
        setEntry(p => ({ ...p, [key]: raw }));
        if (raw !== '' && Number.isFinite(Number(raw))) setCanonical(p => ({ ...p, [key]: key === 'weight' ? toCanonicalWeight(Number(raw), unit) : toCanonicalLength(Number(raw), unit) }));
    };
    return <><label className="field">Measurement system<select name="enteredUnit" value={unit} onChange={e => changeUnit(e.target.value as MeasurementUnit)}><option value="US">US customary — inches and pounds</option><option value="METRIC">Metric — centimeters and kilograms</option></select></label>{(['length','width','height','weight'] as const).map(k => <label className="field" key={k}>{k === 'weight' ? 'Packed weight' : 'Outside ' + k} ({k === 'weight' ? unit === 'US' ? 'lb' : 'kg' : unit === 'US' ? 'in' : 'cm'})<input required type="number" min="0.0001" step="any" name={k + 'Entered'} value={entry[k]} onChange={e => edit(k, e.target.value)}/></label>)}<p className="modal-intro">Changing units converts the displayed values. Shipping calculations use canonical metric quantities, not rounded display values.</p></>;
}
