function endpointAddress(e: { addressLine1: string; addressLine2: string; city: string; state: string; postalCode: string; country: string; }) {
    return [e.addressLine1, e.addressLine2, [e.city, e.state, e.postalCode].filter(Boolean).join(' '), e.country]
        .filter(Boolean)
        .join(' · ');
}

function ReceiptCorrectionHistory({ corrections, files, orgId, canAttach, onAttach }: {
    corrections: NonNullable<Data['equipment'][number]['receiptCorrections']>;
    files: Data['evidence'];
    orgId: string;
    canAttach: boolean;
    onAttach: (index: number) => void;
}) {
    return <details className="correction-history">
        <summary>Observation corrections ({corrections.length}) <span className="correction-history-hint">Audit history &amp; supporting photographs</span></summary>
        <ol className="correction-list">{corrections.map((correction, index) => {
            const attachments = files.filter(file => file.receiptCorrectionIndex === index);
            const evidenceIds = new Set(attachments.map(file => file.id));
            const initial = correction.evidenceId ? files.find(file => file.id === correction.evidenceId && !evidenceIds.has(file.id)) : undefined;
            const linked = initial ? [initial, ...attachments] : attachments;
            return <li className="correction-entry" key={index}>
                <div className="correction-entry-heading">
                    <strong>Correction {index + 1}</strong>
                    <span className={correction.resolved ? 'correction-state resolved' : 'correction-state unresolved'}>{correction.resolved ? 'Resolved' : 'Exception remains'}</span>
                </div>
                <div className="correction-serials">
                    <div><span className="correction-label">Earlier observation</span><code>{correction.previousSerial}</code></div>
                    <div><span className="correction-label">Corrected observation</span><code>{correction.correctedSerial}</code></div>
                </div>
                <div className="correction-reason"><span className="correction-label">Reason</span><p>{correction.reason}</p></div>
                <div className="correction-provenance">Recorded {new Date(correction.at).toLocaleString()} by {correction.actor}</div>
                <div className="correction-attachments">
                    <strong>Supporting evidence ({linked.length})</strong>
                    {linked.map(file => <div className="correction-attachment" key={file.id}>
                        <a className="text-link" href={`/api/evidence/${encodeURIComponent(file.id)}?orgId=${encodeURIComponent(orgId)}`}>{file.name}</a>
                        <span className="correction-label">{nice(file.category || 'OTHER')} · {file.description}</span>
                    </div>)}
                    {!linked.length && <span className="correction-label">No evidence linked to this correction</span>}
                    {canAttach && <button className="secondary" type="button" onClick={() => onAttach(index)}>Attach correction evidence</button>}
                </div>
            </li>;
        })}</ol>
    </details>;
}
